    public override IntPtr Lower(SylvaClient value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override SylvaClient Lift(IntPtr value) {
        return new SylvaClient(value);
    }

    public override SylvaClient Read(BigEndianStream stream) {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(SylvaClient value) {
        return 8;
    }

    public override void Write(SylvaClient value, BigEndianStream stream) {
        stream.WriteLong(Lower(value).ToInt64());
    }
}



/// <summary>
/// What [`Client::connect`] learned, for the Connect screen's confirm step.
/// </summary>
/// <param name="identity_fingerprint">
/// Hex of the server identity public key (the shell formats it for display).
/// </param>
internal record ConnectInfo (
    string @serverName, 
    /// <summary>
    /// Hex of the server identity public key (the shell formats it for display).
    /// </summary>
    string @identityFingerprint, 
    ushort @grpcPort, 
    TrustStatus @trust
) {
}

class FfiConverterTypeConnectInfo: FfiConverterRustBuffer<ConnectInfo> {
    public static FfiConverterTypeConnectInfo INSTANCE = new FfiConverterTypeConnectInfo();

    public override ConnectInfo Read(BigEndianStream stream) {
        return new ConnectInfo(
            @serverName: FfiConverterString.INSTANCE.Read(stream),
            @identityFingerprint: FfiConverterString.INSTANCE.Read(stream),
            @grpcPort: FfiConverterUInt16.INSTANCE.Read(stream),
            @trust: FfiConverterTypeTrustStatus.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(ConnectInfo value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.@serverName)
            + FfiConverterString.INSTANCE.AllocationSize(value.@identityFingerprint)
            + FfiConverterUInt16.INSTANCE.AllocationSize(value.@grpcPort)
            + FfiConverterTypeTrustStatus.INSTANCE.AllocationSize(value.@trust);
    }

    public override void Write(ConnectInfo value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.@serverName, stream);
            FfiConverterString.INSTANCE.Write(value.@identityFingerprint, stream);
            FfiConverterUInt16.INSTANCE.Write(value.@grpcPort, stream);
            FfiConverterTypeTrustStatus.INSTANCE.Write(value.@trust, stream);
    }
}



