/// <summary>
/// Errors surfaced to the shell — deliberately coarse (details go to logs, not
/// the UI). Flat variants so the `uniffi::Error` mapping in 3.6b is clean.
/// </summary>
internal class ClientException: UniffiException {
    ClientException() : base() {}
    ClientException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    public class NotConnected : ClientException {
        public NotConnected() : base() {}
    }
    
    
    public class NotSignedIn : ClientException {
        public NotSignedIn() : base() {}
    }
    
    
    public class Connect : ClientException {
        public Connect() : base() {}
    }
    
    
    public class IdentityMismatch : ClientException {
        public IdentityMismatch() : base() {}
    }
    
    
    public class Crypto : ClientException {
        public Crypto() : base() {}
    }
    
    
    public class SecretKeyRequired : ClientException {
        public SecretKeyRequired() : base() {}
    }
    
    
    public class Storage : ClientException {
        public Storage() : base() {}
    }
    
    
    public class Server : ClientException {
        public Server() : base() {}
    }
    
    

    
}

class FfiConverterTypeClientError : FfiConverterRustBuffer<ClientException>, CallStatusErrorHandler<ClientException> {
    public static FfiConverterTypeClientError INSTANCE = new FfiConverterTypeClientError();

    public override ClientException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ClientException.NotConnected();
            case 2:
                return new ClientException.NotSignedIn();
            case 3:
                return new ClientException.Connect();
            case 4:
                return new ClientException.IdentityMismatch();
            case 5:
                return new ClientException.Crypto();
            case 6:
                return new ClientException.SecretKeyRequired();
            case 7:
                return new ClientException.Storage();
            case 8:
                return new ClientException.Server();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeClientError.Read()", value));
        }
    }

    public override int AllocationSize(ClientException value) {
        switch (value) {

            case ClientException.NotConnected variant_value:
                return 4;

            case ClientException.NotSignedIn variant_value:
                return 4;

            case ClientException.Connect variant_value:
                return 4;

            case ClientException.IdentityMismatch variant_value:
                return 4;

            case ClientException.Crypto variant_value:
                return 4;

            case ClientException.SecretKeyRequired variant_value:
                return 4;

            case ClientException.Storage variant_value:
                return 4;

            case ClientException.Server variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeClientError.AllocationSize()", value));
        }
    }

    public override void Write(ClientException value, BigEndianStream stream) {
        switch (value) {
            case ClientException.NotConnected variant_value:
                stream.WriteInt(1);
                break;
            case ClientException.NotSignedIn variant_value:
                stream.WriteInt(2);
                break;
            case ClientException.Connect variant_value:
                stream.WriteInt(3);
                break;
            case ClientException.IdentityMismatch variant_value:
                stream.WriteInt(4);
                break;
            case ClientException.Crypto variant_value:
                stream.WriteInt(5);
                break;
            case ClientException.SecretKeyRequired variant_value:
                stream.WriteInt(6);
                break;
            case ClientException.Storage variant_value:
                stream.WriteInt(7);
                break;
            case ClientException.Server variant_value:
                stream.WriteInt(8);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeClientError.Write()", value));
        }
    }
}





/// <summary>
/// The outcome of a sign-in attempt.
/// </summary>
internal record SignInOutcome {
    
    public record Success (
        string @userId
    ) : SignInOutcome {}
    
    /// <summary>
    /// The account has a second factor; the shell must complete MFA (not yet
    /// supported by this client — slice 1).
    /// </summary>
    public record MfaRequired: SignInOutcome {}
    
    

    
}

class FfiConverterTypeSignInOutcome : FfiConverterRustBuffer<SignInOutcome>{
    public static FfiConverterRustBuffer<SignInOutcome> INSTANCE = new FfiConverterTypeSignInOutcome();

    public override SignInOutcome Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new SignInOutcome.Success(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new SignInOutcome.MfaRequired(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSignInOutcome.Read()", value));
        }
    }

    public override int AllocationSize(SignInOutcome value) {
        switch (value) {
            case SignInOutcome.Success variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@userId);
            case SignInOutcome.MfaRequired variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSignInOutcome.AllocationSize()", value));
        }
    }

    public override void Write(SignInOutcome value, BigEndianStream stream) {
        switch (value) {
            case SignInOutcome.Success variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@userId, stream);
                break;
            case SignInOutcome.MfaRequired variant_value:
                stream.WriteInt(2);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSignInOutcome.Write()", value));
        }
    }
}







/// <summary>
/// Whether this is the first time we've seen a server (pin it) or it matches the
/// stored pin.
/// </summary>
internal enum TrustStatus: int {
    
    FirstContact,
    Trusted
}

class FfiConverterTypeTrustStatus: FfiConverterRustBuffer<TrustStatus> {
    public static FfiConverterTypeTrustStatus INSTANCE = new FfiConverterTypeTrustStatus();

    public override TrustStatus Read(BigEndianStream stream) {
        var value = stream.ReadInt() - 1;
        if (Enum.IsDefined(typeof(TrustStatus), value)) {
            return (TrustStatus)value;
        } else {
            throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeTrustStatus.Read()", value));
        }
    }

    public override int AllocationSize(TrustStatus value) {
        return 4;
    }

    public override void Write(TrustStatus value, BigEndianStream stream) {
        stream.WriteInt((int)value + 1);
    }
}






class FfiConverterOptionalString: FfiConverterRustBuffer<string?> {
    public static FfiConverterOptionalString INSTANCE = new FfiConverterOptionalString();

    public override string? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterString.INSTANCE.Read(stream);
    }

    public override int AllocationSize(string? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterString.INSTANCE.AllocationSize((string)value);
        }
    }

    public override void Write(string? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterString.INSTANCE.Write((string)value, stream);
        }
    }
}




class FfiConverterSequenceTypeDeviceInfo: FfiConverterRustBuffer<List<DeviceInfo>> {
    public static FfiConverterSequenceTypeDeviceInfo INSTANCE = new FfiConverterSequenceTypeDeviceInfo();

    public override List<DeviceInfo> Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        var result = new List<DeviceInfo>(length);
        var readFn = FfiConverterTypeDeviceInfo.INSTANCE.Read;
        for (int i = 0; i < length; i++) {
            result.Add(readFn(stream));
        }
        return result;
    }

    public override int AllocationSize(List<DeviceInfo> value) {
        var sizeForLength = 4;

        // details/1-empty-list-as-default-method-parameter.md
        if (value == null) {
            return sizeForLength;
        }

        var allocationSizeFn = FfiConverterTypeDeviceInfo.INSTANCE.AllocationSize;
        var sizeForItems = value.Sum(item => allocationSizeFn(item));
        return sizeForLength + sizeForItems;
    }

    public override void Write(List<DeviceInfo> value, BigEndianStream stream) {
        // details/1-empty-list-as-default-method-parameter.md
        if (value == null) {
            stream.WriteInt(0);
            return;
        }

        stream.WriteInt(value.Count);
        var writerFn = FfiConverterTypeDeviceInfo.INSTANCE.Write;
        value.ForEach(item => writerFn(item, stream));
    }
}
